(() => {
const I=(name)=>`<i data-lucide="${name}"></i>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const channelNames={local:'本地企微机器人',xd:'先胜小D'};
const people=[['p1','周文俊','JiaoWoRuGeHaoLe'],['p2','林晓','linxiao'],['p3','李明','liming'],['p4','张伟','zhangwei'],['p5','王芳','wangfang'],['unknown','未解析用户','woeX4J…7Qp']];
// 全部为本地静态示例；未连接真实会话、成员缓存或统计接口。
const records=[];
const counts=[[4,3],[2,4],[3,1],[2,0],[1,2],[0,2]];
people.forEach((p,n)=>['local','xd'].forEach((ch,j)=>{for(let k=0;k<counts[n][j];k++)records.push({person:p[0],channel:ch,day:14-((n+k+j)%7),messages:2+(n+k)%4,group:k%3===2?'wreX4JEA…R8sQ':null,title:['请帮我查看本月销售情况','文档可以转换为 Word 吗？','如何配置模型参数？'][k%3]});}));
let state={view:'stats',channel:'local',agent:'all',days:7,source:'channel',tab:'users',search:'',originView:'overview',selectedUser:null,selectedSession:0,history:false,lookup:true,detailTab:'chat',detailRecord:null,detailPerson:null};
const subset=(ch=state.channel)=>records.filter(r=>r.channel===ch&&r.day>14-state.days);
let originFilters=null;
function countsOf(rows){return{users:new Set(rows.map(r=>r.person)).size,sessions:rows.length,messages:rows.reduce((a,r)=>a+r.messages,0)};}
const navigation=[['测试','message-square'],['Agent','bot'],['集成','puzzle'],['渠道','radio'],['设置',null],['模型','sparkles'],['工具','wrench'],['MCP','plug'],['Skill','book-open'],['诊断',null],['日志','list'],['会话','messages-square']];
const help=text=>`<button class="help" aria-label="统计说明">${I('circle-help')}<span class="tip" role="tooltip">${text}</span></button>`;
function dropdown(kind,label,options,icon){return `<div class="dropdown"><button data-menu="${kind}" aria-expanded="false"><span>${I(icon)}${label}</span>${I('chevron-down')}</button><div class="menu" id="menu-${kind}" hidden>${options.map(([v,t])=>`<button data-filter="${kind}" data-value="${v}" role="option" aria-selected="${String(state[kind])===String(v)}">${t}</button>`).join('')}</div></div>`;}
function toolbar(stats){return `<div class="toolbar">${stats?'':dropdown('agent',state.agent==='all'?'全部 Agent':state.agent==='local'?'local企微助手':'先胜小D',[['all','全部 Agent'],['local','local企微助手'],['xd','先胜小D']],'bot')}${dropdown('days',state.days===1?'今天':`最近 ${state.days} 天`,[[1,'今天'],[7,'最近 7 天'],[30,'最近 30 天']],'clock')}${stats?'':dropdown('source',{all:'全部来源',channel:'渠道',normal:'普通'}[state.source],[['all','全部来源'],['channel','渠道'],['normal','普通']],'database')}<button class="primary" data-action="query">${I('search')}查询</button><button data-action="reset">${I('rotate-ccw')}重置</button></div>`;}
function summary(rows){const c=countsOf(rows);return `<section class="usage-summary"><div class="summary-heading">使用情况 ${help('统计所选账户和时间内在私聊或群聊发过消息的成员，同一成员去重。按已确认的企微应用身份合并，与平台会话所有者分开；未确认身份按账户与原始 ID 区分。')}</div><div class="summary">${[['users','活跃用户'],['sessions','会话数'],['messages','用户消息']].map(([key,label])=>`<div><span>${label}</span><strong>${c[key]}</strong></div>`).join('')}</div><p class="summary-caption">${channelNames[state.channel]} · ${state.days===1?'今天':`最近 ${state.days} 天`}</p></section>`;}
function cards(){const local=state.channel==='local';return `<section class="account-info" aria-label="渠道账户与企微应用"><div class="account-card-title"><span class="account-emblem"><img src="wecom.png" alt="企业微信"></span><div><h2>${channelNames[state.channel]}</h2><span class="secondary">企业微信 · WebSocket</span></div><span class="connection"><span class="dot"></span>已连接</span></div><div class="account-facts"><span>绑定 Agent</span><strong>${local?'local企微助手':'先胜小D'}</strong><span>会话用户</span><strong>ruge</strong></div><div class="application-block"><div class="application-title">${I('blocks')}<strong>成员资料查询</strong><span class="enabled">${state.lookup?'用户详情已启用':'姓名查询未开启'}</span></div><div class="account-facts"><span>企微 Agent ID</span><strong>1000025</strong><span>企业 ID</span><strong class="mono">ww9ff07…49ed5</strong></div></div></section>`;}
function channelSwitch(){return `<div class="channel-switch" role="group" aria-label="渠道账户筛选">${Object.entries(channelNames).map(([id,name])=>`<button data-channel="${id}" class="${state.channel===id?'active':''}" aria-pressed="${state.channel===id}">${id==='all'?I('layers'):'<img src="wecom.png" alt="企微">'}${name}</button>`).join('')}</div>`;}
function groups(rows){const m=new Map();rows.forEach(r=>{const key=state.tab==='users'?r.person:(r.group?`${r.channel}:${r.group}`:null);if(!key)return;if(!m.has(key))m.set(key,[]);m.get(key).push(r);});return [...m.entries()].map(([id,rs])=>{const p=people.find(p=>p[0]===id);return {id,name:p?(state.lookup&&p[0]!=='unknown'?p[1]:'用户'):'群聊',raw:p?p[2]:rs[0].group,rows:rs.slice().sort((a,b)=>b.day-a.day)};}).filter(p=>`${p.name} ${p.raw}`.toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>b.rows.length-a.rows.length);}
function selectedGroup(rows){const list=groups(rows);let g=list.find(g=>g.id===state.selectedUser);if(!g){g=list[0];state.selectedUser=g?.id||null;state.selectedSession=0;}return g;}
function identity(g){return `${esc(g.name)} <span class="identity-dot">·</span> <span class="identity-raw">${esc(g.raw)}</span>`;}
function copyButton(r){return `<button class="copy-session" data-copy-session="${sessionId(r)}" aria-label="复制会话 ID" title="复制完整会话 ID">${I('copy')}</button>`;}
function table(rows){const gs=groups(rows),selected=selectedGroup(rows);return `<div class="table-wrap"><table aria-label="${state.tab==='users'?'渠道用户':'群聊'}列表"><colgroup><col class="identity-col"><col style="width:70px"><col style="width:70px"><col style="width:103px"><col style="width:42px"></colgroup><thead><tr><th>${state.tab==='users'?'渠道用户':'群聊'}</th><th title="包含最近会话">历史会话</th><th>用户消息</th><th>最近活跃</th><th><span class="sr-only">操作</span></th></tr></thead><tbody>${gs.length?gs.map(g=>{const r=g.rows[0];return `<tr data-person="${g.id}" tabindex="0" aria-selected="${selected?.id===g.id}" class="${selected?.id===g.id?'selected':''}" title="查看最近会话"><td><div class="member-cell"><span class="table-avatar ${state.tab==='groups'?'group-avatar':'user-avatar'}" role="img" aria-label="${state.tab==='groups'?'群聊':'用户'}">${I(state.tab==='groups'?'users':'user')}</span><div class="member-cell-text"><div class="identity-line" title="${esc(g.name+' · '+g.raw)}">${identity(g)}</div><div class="session-subline">${copyButton(r)}<span class="mono">${sessionId(r).slice(0,8)}</span><span>·</span><span class="question-excerpt" title="${esc(r.title)}">${esc(r.title)}</span></div></div></div></td><td class="number">${g.rows.length}</td><td class="number">${g.rows.reduce((a,r)=>a+r.messages,0)}</td><td class="number">${sessionStamp(r)}</td><td><button class="row-open" data-row-open="${g.id}" aria-label="打开${esc(g.name)}的最近会话" title="打开最近会话">${I('arrow-up-right')}</button></td></tr>`;}).join(''):`<tr><td colspan="5" class="empty">没有符合当前条件的${state.tab==='users'?'用户':'群聊'}</td></tr>`}</tbody></table></div><div class="footline"><span>历史会话包含最近一条</span><div class="pagination"><button disabled>上一页</button><span>1 / 1 · 共 ${gs.length} 项</span><button disabled>下一页</button></div></div>`;}
function sessionStamp(r){return `09-${String(r.day).padStart(2,'0')} 13:58`;}
function sessionId(r){return (records.indexOf(r)+1).toString(16).padStart(8,'0')+'-7c32-4b91-a021';}
function reply(r){return r.title.includes('销售')?'可以，请确认要查看的销售模型和月份，我会按对应范围查询。':r.title.includes('Word')?'可以，请上传需要转换的文档，我会帮助你处理。':'可以，请告诉我需要调整的模型及具体参数。';}
function sessionListItem(r,index,latest=false){return `<article class="session-list-item ${latest?'dominant-session':''}" aria-label="会话 ${sessionId(r).slice(0,8)}">${copyButton(r)}<button class="session-entry-open" data-open-session="${index}" aria-label="打开会话 ${sessionId(r).slice(0,8)}"><span class="session-entry-heading"><span class="mono">${sessionId(r).slice(0,8)}</span><span class="session-question-count" title="提问数">${I('message-circle')} ${r.messages}</span>${latest?'<span class="current-session-pill">最近</span>':''}<time>${sessionStamp(r)}</time>${I('arrow-up-right')}</span><span class="session-entry-question">${esc(r.title)}</span></button></article>`;}
function linkedSessions(rows){const g=selectedGroup(rows);if(!g)return `<aside class="linked-sessions"><div class="linked-empty">${I('messages-square')}暂无会话</div></aside>`;const current=g.rows[0];return `<aside class="linked-sessions compact-inspector session-list-inspector" aria-label="最近会话与历史会话"><div class="compact-identity inspector-person"><strong>${esc(g.name)}</strong><span>${esc(g.raw)}</span></div><div class="inspector-session-sections"><section class="dominant-session-region">${sessionListItem(current,0,true)}</section><section class="older-session-region"><h3>历史会话 <span>${g.rows.length-1}</span></h3><div class="older-session-scroll">${g.rows.slice(1).map((r,i)=>sessionListItem(r,i+1)).join('')||'<p class="no-older-sessions">暂无其他历史会话</p>'}</div></section></div></aside>`;}
function showNotice(message){document.querySelector('.prototype-toast')?.remove();const toast=document.createElement('div');toast.className='prototype-toast';toast.setAttribute('role','status');toast.textContent=message;document.body.append(toast);setTimeout(()=>toast.remove(),3500);}
function sessionDetail(){const r=state.detailRecord,p=state.detailPerson;return `<section class="full-session"><div class="full-session-head"><div><h2>${esc(r.title)}</h2><span class="secondary mono">会话 ID：${sessionId(r)}</span></div><div class="segmented"><button data-detail-tab="chat" class="${state.detailTab==='chat'?'active':''}">对话</button><button data-detail-tab="trace" class="${state.detailTab==='trace'?'active':''}">轨迹</button></div></div><div class="full-session-body"><div class="full-session-content">${state.detailTab==='chat'?`<div class="conversation-date">2026-${sessionStamp(r)}</div><div class="detail-message"><div class="message-author">${I('user')}${esc(p.name)}<time>13:58:00</time></div><div class="message-bubble">${esc(r.title)}</div></div><div class="detail-message"><div class="message-author">${I('sparkles')}助手<time>13:58:02</time></div><p>${reply(r)}</p></div><div class="readonly-note">${I('eye')}历史会话 · 只读</div>`:`<div class="trace-toolbar">${I('list-ordered')}顺序轨迹 <span>3 条记录</span></div>${[['标题',r.title,'13:57:59.623'],['用户',r.title,'13:58:00.138'],['助手',reply(r),'13:58:02.596']].map(([role,body,time],i)=>`<button class="trace-item ${state.traceIndex===i?'active':''}" data-trace="${i}"><span class="trace-role role-${i}">${role}</span><span class="trace-text">${esc(body)}</span><time>${time}</time><span class="trace-status">Completed</span></button>`).join('')}`}</div><aside class="session-detail-aside">${state.detailTab==='chat'?`<h3>概览</h3><dl class="session-facts"><div><dt>会话状态</dt><dd class="status-complete">已完成</dd></div><div><dt>渠道用户</dt><dd>${esc(p.name)}</dd></div><div><dt>用户 ID</dt><dd>${esc(p.raw)}</dd></div><div><dt>用户消息</dt><dd>${r.messages} 条</dd></div><div><dt>最近活动</dt><dd>2026-${sessionStamp(r)}</dd></div></dl>`:`<h3>${['标题','用户','助手'][state.traceIndex||0]} · 记录详情</h3><div class="trace-detail-tabs">摘要</div><span class="secondary">${I('clock')} 已完成</span><p>${esc((state.traceIndex||0)===2?reply(r):r.title)}</p>`}</aside></div></section>`;}
function workbench(rows){return `<div class="linked-workbench"><div class="member-table">${table(rows)}</div>${linkedSessions(rows)}</div>`;}
function activeUsers(rows){
 const totals=new Map();rows.forEach(r=>totals.set(r.person,(totals.get(r.person)||0)+r.messages));
 const ranked=[...totals].sort((a,b)=>b[1]-a[1]).slice(0,5);
 return `<aside class="active-users" aria-label="活跃用户前五名"><div class="ranking-heading"><h2>活跃用户</h2><span>前 5 名</span>${help('按所选账户和时间内的用户消息数排序，包含私聊和群聊发言。同一成员只计一次；未确认身份按账户与原始 ID 区分。点击成员筛选下方用户列表。')}</div><div class="ranking-columns"><span>成员</span><span>用户消息</span></div>${ranked.map(([id,count],n)=>{const p=people.find(p=>p[0]===id);return `<button class="ranking-row" data-ranked-user="${id}" title="${esc(p[2])}"><span class="rank">${n+1}</span><span class="rank-name">${esc(state.lookup&&p[0]!=='unknown'?p[1]:p[2])}</span><strong>${count}</strong></button>`;}).join('')||'<p class="muted">当前范围暂无活跃用户</p>'}<p class="ranking-foot">私聊 + 群聊 · 按成员去重</p></aside>`;
}
function stats(){const rs=subset();return `<section class="channel-body"><div class="channel-top"><aside class="account-picker"><h2>渠道账户</h2>${channelSwitch()}</aside><div class="account-overview">${summary(rs)}<div class="overview-cards">${cards()}${activeUsers(rs)}</div></div></div><div class="channel-lower"><section class="stats-detail"><div class="table-tools"><div class="left"><div class="segmented"><button data-tab="users" class="${state.tab==='users'?'active':''}">${I('users')}用户</button><button data-tab="groups" class="${state.tab==='groups'?'active':''}">${I('messages-square')}群聊</button></div></div><label class="search">${I('search')}<input id="search" value="${esc(state.search)}" placeholder="${state.tab==='users'?'搜索渠道用户姓名或 ID':'搜索群聊 ID'}" aria-label="搜索渠道用户姓名或 ID"></label></div><div id="results">${workbench(rs)}</div></section></div></section>`;}
function origin(){return `<div class="table-tools"><label class="search">${I('search')}<input placeholder="搜索会话名称或 ID" aria-label="搜索会话名称或 ID" id="origin-search"></label><span style="color:var(--muted);font-size:12px">${state.source==='normal'?'普通会话':state.source==='channel'?'渠道会话':'全部会话'}</span></div><div class="overview-stats" style="${state.originView==='list'?'display:none':''}"><div><strong>${state.source==='normal'?4:state.source==='all'?28:24}</strong><small>会话数</small></div><div><strong>1</strong><small>平台用户</small></div><div><strong>${state.source==='normal'?10:state.source==='all'?84:74}</strong><small>用户提问</small></div></div><div class="table-wrap"><table><thead><tr><th>会话</th><th>Agent</th><th>用户</th><th>来源</th><th>最近活动</th></tr></thead><tbody><tr><td><strong>${state.source==='normal'?'你好':'User｜周文俊(JiaoWoRuGeHaoLe)'}</strong><span class="secondary">4a4b17e3 · 请帮我查看本月销售情况</span></td><td>先胜小D</td><td>ruge</td><td>${state.source==='normal'?'普通':'渠道'}</td><td>2026-09-14 13:58</td></tr><tr><td><strong>${state.source==='normal'?'文档格式转换':'User｜林晓(linxiao)'}</strong><span class="secondary">5bc639a1 · 文档可以转换为 Word 吗？</span></td><td>local企微助手</td><td>ruge</td><td>${state.source==='normal'?'普通':'渠道'}</td><td>2026-09-14 12:30</td></tr></tbody></table></div><p class="flat-note">${I('info')}这是入口示意。点击右上角“只看渠道”，可查看渠道发送人的使用情况。</p>`;}
function render(){const isStats=state.view==='stats',isDetail=state.view==='session';document.body.className='channel-review '+(isStats?'channel-stats-view':isDetail?'session-detail-view':'');document.body.innerHTML=`<div class="review"><strong>渠道统计 · HTML 原型</strong><button data-action="${isDetail?'return-stats':isStats?'back':'enter'}">${isDetail?'返回渠道统计':isStats?'查看「只看渠道」入口':'查看渠道专页'}</button><span class="right"><button data-action="toggle-lookup">示例：姓名查询${state.lookup?'已开启':'未开启'}</button>示例数据 · 可切换 / 搜索</span></div><div class="shell"><aside class="rail"><div class="brand"><span class="brand-icon">${I('bot')}</span><span><strong>DeepAgent</strong><small><span class="dot"></span>已连接</small></span></div><nav>${navigation.map(([n,i])=>i?`<span class="navitem ${n==='会话'?'active':''}">${I(i)}${n}</span>`:`<div class="section-label">${n}</div>`).join('')}</nav><div class="rail-foot"><div>${I('settings-2')}全局配置</div><div>${I('library')}模型目录</div><div>${I('book-open')}接口文档</div><div class="profile">${I('circle-user')}本地用户</div></div></aside><main><header><div class="heading"><div><h1>${isDetail?`<button class="breadcrumb" data-action="return-stats">${I('arrow-left')}渠道统计</button>${I('chevron-right')}会话详情`:isStats?`<button class="breadcrumb" data-action="back">会话</button>${I('chevron-right')}渠道统计`:'会话'}</h1><p>${isDetail?'查看历史对话与执行轨迹。':isStats?'按渠道账户查看用户、群聊与使用情况。':'了解用户提问与使用情况，查看完整会话。'}</p></div>${isDetail?'':toolbar(isStats)}</div><div class="range-line" ${isStats||isDetail?'hidden':''}><span></span><div class="right"><span>${state.days===1?'2026-09-14':state.days===7?'2026-09-08':'2026-08-16'} 00:00 — 2026-09-14 23:59 · Asia/Shanghai</span>${isStats?'':`<button class="stats-entry" data-action="enter">${I('radio')}只看渠道</button><div class="segmented"><button data-origin="overview" class="${state.originView==='overview'?'active':''}">${I('layout-grid')}概览</button><button data-origin="list" class="${state.originView==='list'?'active':''}">${I('list')}列表</button></div>`}</div></div></header>${isDetail?sessionDetail():isStats?stats():origin()}</main></div>`;icons();}
function icons(){window.lucide.createIcons();}
function refreshResults(){const scroll=document.querySelector('.related-session-list')?.scrollTop||0;document.querySelector('#results').innerHTML=workbench(subset());const list=document.querySelector('.related-session-list');if(list)list.scrollTop=scroll;icons();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-person]');if(!b)return;
 if(b.dataset.copySession){try{await navigator.clipboard.writeText(b.dataset.copySession);showNotice('会话 ID 已复制');}catch{showNotice('无法自动复制，请复制会话 ID：'+b.dataset.copySession);}return;}
 if(b.dataset.menu){const menu=document.getElementById('menu-'+b.dataset.menu),was=menu.hidden;document.querySelectorAll('.menu').forEach(el=>el.hidden=true);menu.hidden=!was;b.setAttribute('aria-expanded',String(was));return;}
 document.querySelectorAll('.menu').forEach(el=>el.hidden=true);
 if(b.dataset.filter){state[b.dataset.filter]=b.dataset.filter==='days'?Number(b.dataset.value):b.dataset.value;render();}
 if(b.dataset.channel){state.channel=b.dataset.channel;state.search='';state.selectedSession=0;state.history=false;render();}
 if(b.dataset.tab){state.tab=b.dataset.tab;state.search='';state.selectedSession=0;state.history=false;render();}
 if(b.dataset.origin){state.originView=b.dataset.origin;render();}
 if(b.dataset.person){state.selectedUser=b.dataset.person;state.selectedSession=0;state.history=false;refreshResults();}
 if(b.dataset.action==='history'){state.history=true;refreshResults();}
 if(b.dataset.action==='latest'){state.history=false;refreshResults();}
 if(b.dataset.openSession!==undefined||b.dataset.rowOpen){const g=b.dataset.rowOpen?groups(subset()).find(g=>g.id===b.dataset.rowOpen):selectedGroup(subset());const r=g.rows[Number(b.dataset.openSession||0)];showNotice('打开会话 '+sessionId(r).slice(0,8)+'：正式实现复用现有会话详情（对话 / 轨迹）。');}
 if(b.dataset.action==='toggle-lookup'){state.lookup=!state.lookup;state.search='';render();}
 if(b.dataset.detailTab){state.detailTab=b.dataset.detailTab;render();}
 if(b.dataset.trace!==undefined){state.traceIndex=Number(b.dataset.trace);render();}
 if(b.dataset.action==='return-stats'){state.view='stats';render();}
 if(b.dataset.rankedUser){const p=people.find(p=>p[0]===b.dataset.rankedUser);state.tab='users';state.search=p[2];render();document.querySelector('#search')?.focus();}
 if(b.dataset.action==='back'){state.view='origin';if(originFilters)Object.assign(state,originFilters);render();}
 if(b.dataset.action==='enter'){originFilters={agent:state.agent,source:state.source,days:state.days,originView:state.originView};state.view='stats';render();}
 if(b.dataset.action==='reset'){state.days=7;state.channel='local';state.history=false;state.search='';if(state.view==='origin'){state.source='all';state.agent='all';}render();}
 if(b.dataset.action==='query'){render();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;refreshResults();}if(e.target.id==='origin-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-person]')){e.preventDefault();e.target.click();document.querySelector('[data-person].selected')?.focus();}if(e.key==='Escape'){document.querySelectorAll('.menu').forEach(el=>el.hidden=true);}});
render();
})();
